import CryptoKit
import Foundation
import Testing
@testable import HerdrKit

/// The Swift Noise implementation must match the relay's Go reference
/// (flynn/noise, `cmd/noise-vectors` in herdrm-relay) byte for byte, so a
/// phone and a Mac built from either side always agree.
struct RelayNoiseTests {
    // Generated by `go run ./cmd/noise-vectors` in herdrm-relay.
    static let v: [String: String] = [
        "host_id": "abcdefghijklmnopqrstuvwxyz",
        "psk": "0505050505050505050505050505050505050505050505050505050505050505",
        "phone_static_private": "0101010101010101010101010101010101010101010101010101010101010101",
        "phone_static_public": "a4e09292b651c278b9772c569f5fa9bb13d906b46ab68c9df9dc2b4409f8a209",
        "mac_static_private": "0202020202020202020202020202020202020202020202020202020202020202",
        "mac_static_public": "ce8d3ad1ccb633ec7b70c17814a5c76ecd029685050d344745ba05870e587d59",
        "phone_ephemeral_private": "0303030303030303030303030303030303030303030303030303030303030303",
        "mac_ephemeral_private": "0404040404040404040404040404040404040404040404040404040404040404",
        "payload1": "7b2276223a317d",
        "payload2": "7b2276223a312c226e616d65223a224d6163227d",
        "msg1": "5dfedd3b6bd47f6fa28ee15d969d5bb0ea53774d488bdaf9df1c6e0124b3ef226573deb220f700f6d4b76a72b83dfa72b4eed7f9eb8ff1313611b4d7ec8c9ebfd5e400f7b9d557141a306338834dfc93494441ab1e87e735877e3ff255b7f958e39a381caf00f8",
        "msg2": "ac01b2209e86354fb853237b5de0f4fab13c7fcbf433a61c019369617fecf10bbedb6c3a3b3ad798a9fb45a639476802d9b38e0a284ea3e78c8732fcd1f432a599a048fe",
        "phone_to_mac_0": "b300d89fb776f9791fc15941f16ef0defc2f4b96eb43e2cb29b2e941623e8dbd",
        "phone_to_mac_1": "b5b7172f9095c3fc9075a550ac6667385bf686bd9673",
        "mac_to_phone_0": "75417b60d43e3087b588a03e2b32816f12a5e3941dd8d26cdf014762e7bb",
        "handshake_hash": "c69fad21ccd2ae67d0f4763fd7644af6440778bc8b4fa0bd92be2fa928102ae8",
    ]

    static func hex(_ key: String) -> Data {
        let s = v[key]!
        var data = Data()
        var i = s.startIndex
        while i < s.endIndex {
            let j = s.index(i, offsetBy: 2)
            data.append(UInt8(s[i..<j], radix: 16)!)
            i = j
        }
        return data
    }

    static func key(_ name: String) throws -> Curve25519.KeyAgreement.PrivateKey {
        try .init(rawRepresentation: hex(name))
    }

    @Test func matchesTheGoReferenceByteForByte() throws {
        let prologue = RelayNoise.prologue(hostID: Self.v["host_id"]!)
        #expect(try Self.key("phone_static_private").publicKey.rawRepresentation == Self.hex("phone_static_public"))

        var phone = try NoiseInitiator(
            prologue: prologue, staticKey: Self.key("phone_static_private"),
            responderStatic: Self.hex("mac_static_public"), psk: Self.hex("psk"),
            ephemeral: Self.key("phone_ephemeral_private"))
        var mac = NoiseResponder(
            prologue: prologue, staticKey: try Self.key("mac_static_private"),
            ephemeral: try Self.key("mac_ephemeral_private"))

        let m1 = try phone.writeMessage1(payload: Self.hex("payload1"))
        #expect(m1 == Self.hex("msg1"))
        #expect(try mac.readMessage1(m1) == Self.hex("payload1"))
        #expect(mac.initiatorStatic == Self.hex("phone_static_public"))

        let (m2, macSession) = try mac.writeMessage2(payload: Self.hex("payload2"), psk: Self.hex("psk"))
        #expect(m2 == Self.hex("msg2"))
        let (reply, phoneSession) = try phone.readMessage2(m2)
        #expect(reply == Self.hex("payload2"))
        #expect(phoneSession.handshakeHash == Self.hex("handshake_hash"))
        #expect(macSession.handshakeHash == Self.hex("handshake_hash"))

        var phoneSend = phoneSession.send
        var macReceive = macSession.receive
        var macSend = macSession.send
        var phoneReceive = phoneSession.receive
        #expect(try phoneSend.encrypt(Data("hello from phone".utf8)) == Self.hex("phone_to_mac_0"))
        #expect(try phoneSend.encrypt(Data("second".utf8)) == Self.hex("phone_to_mac_1"))
        #expect(try macSend.encrypt(Data("hello from mac".utf8)) == Self.hex("mac_to_phone_0"))
        #expect(try macReceive.decrypt(Self.hex("phone_to_mac_0")) == Data("hello from phone".utf8))
        #expect(try phoneReceive.decrypt(Self.hex("mac_to_phone_0")) == Data("hello from mac".utf8))
    }

    @Test func aWrongPSKFailsOnThePhone() throws {
        let prologue = RelayNoise.prologue(hostID: "h")
        let macKey = Curve25519.KeyAgreement.PrivateKey()
        var phone = try NoiseInitiator(prologue: prologue, staticKey: .init(),
                                       responderStatic: macKey.publicKey.rawRepresentation,
                                       psk: Data(repeating: 1, count: 32))
        var mac = NoiseResponder(prologue: prologue, staticKey: macKey)
        _ = try mac.readMessage1(try phone.writeMessage1(payload: Data()))
        let (m2, _) = try mac.writeMessage2(payload: Data(), psk: Data(repeating: 2, count: 32))
        #expect(throws: RelayNoise.Failure.decryptionFailed) { _ = try phone.readMessage2(m2) }
    }

    @Test func aPhoneWithTheWrongMacKeyIsNotUnderstood() throws {
        let prologue = RelayNoise.prologue(hostID: "h")
        var phone = try NoiseInitiator(prologue: prologue, staticKey: .init(),
                                       responderStatic: Curve25519.KeyAgreement.PrivateKey().publicKey.rawRepresentation,
                                       psk: Data(repeating: 1, count: 32))
        var mac = NoiseResponder(prologue: prologue, staticKey: .init())
        #expect(throws: RelayNoise.Failure.decryptionFailed) {
            _ = try mac.readMessage1(try phone.writeMessage1(payload: Data()))
        }
    }

    @Test func aTamperedTransportMessageIsRejectedAndDoesNotAdvanceTheNonce() throws {
        let prologue = RelayNoise.prologue(hostID: "h")
        let macKey = Curve25519.KeyAgreement.PrivateKey()
        let psk = Data(repeating: 9, count: 32)
        var phone = try NoiseInitiator(prologue: prologue, staticKey: .init(),
                                       responderStatic: macKey.publicKey.rawRepresentation, psk: psk)
        var mac = NoiseResponder(prologue: prologue, staticKey: macKey)
        _ = try mac.readMessage1(try phone.writeMessage1(payload: Data()))
        let (m2, macSession) = try mac.writeMessage2(payload: Data(), psk: psk)
        var phoneSession = try phone.readMessage2(m2).session
        var receive = macSession.receive
        let good = try phoneSession.send.encrypt(Data("x".utf8))
        var bad = good
        bad[0] ^= 1
        #expect(throws: RelayNoise.Failure.decryptionFailed) { _ = try receive.decrypt(bad) }
        #expect(try receive.decrypt(good) == Data("x".utf8), "the failed frame did not use up nonce 0")
    }
}
